local VERSION='10.0.0'
local bloodBank, commandKits, resilience = {}, {}, {}
local function uid(p)return('%s-%s-%04d'):format(p,os.time(),math.random(0,9999))end
exports('ReserveMassiveTransfusionV10',function(patientCid,units,ratios,actor)local item={id=uid('MTP10'),patientCid=patientCid,units=units or{},ratios=ratios or{rbc=1,plasma=1,platelets=1},actor=actor,status='reserved',createdAt=os.time()};bloodBank[item.id]=item;return item.id,item end)
exports('BuildCriticalCommandKitV10',function(profile,stock)local templates={hemorrhage={tourniquet=6,gauze=12,chest_seal=6,blood=6,warmer=1},airway={airway_kit=4,oxygen=4,capnography=2,ventilator=1},mci={tourniquet=12,gauze=24,chest_seal=12,triage_tags=50}};local required=templates[tostring(profile)]or templates.hemorrhage;local shortages={};for item,count in pairs(required)do local available=tonumber(stock and stock[item])or 0;if available<count then shortages[item]=count-available end end;local kit={id=uid('KIT10'),profile=profile,required=required,shortages=shortages,status=next(shortages)and'incomplete'or'ready',createdAt=os.time()};commandKits[kit.id]=kit;return kit.status=='ready',kit end)
exports('CalculateSupplyResilienceV10',function(stock,burnRate,hours)local score=100;local risks={};for item,rate in pairs(burnRate or{})do local cover=(tonumber(stock and stock[item])or 0)/math.max(.1,tonumber(rate)or .1);if cover<(tonumber(hours)or 24)then score=score-10;risks[item]=cover end end;local result={id=uid('SUP10'),score=math.max(0,score),coverage=risks,status=score>=80 and'resilient'or score>=55 and'vulnerable'or'critical',createdAt=os.time()};resilience[result.id]=result;return result end)
exports('GetV10InventoryBoard',function()return{version=VERSION,bloodBank=bloodBank,commandKits=commandKits,resilience=resilience,generatedAt=os.time()}end)
CreateThread(function()Wait(8600);pcall(function()exports['dpn-medical-core']:RegisterModule('dpn-medical-inventory',VERSION,{'massive_transfusion_reservation','critical_command_kits','supply_resilience','blood_bank_command'})end);print('[dpn-medical-inventory] v10 blood-bank command and supply resilience active')end)
